import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) words.add(sc.next());
        List<String> lines = new ArrayList<>();
        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<String>> futures = new ArrayList<>();
            for (String word : words) futures.add(pool.submit(() -> word + ":" + word.length() + ":" + word.getBytes(StandardCharsets.UTF_8).length));
            for (Future<String> f : futures) lines.add(f.get());
        }
        Path path = Path.of("words.txt");
        Files.write(path, lines, StandardCharsets.UTF_8);
        List<String> read = Files.readAllLines(path, StandardCharsets.UTF_8);
        for (int i = 0; i < read.size(); i++) System.out.println((i + 1) + ":" + read.get(i));
        int chars = 0, bytes = 0;
        for (String word : words) {
            chars += word.length();
            bytes += word.getBytes(StandardCharsets.UTF_8).length;
        }
        System.out.println("chars=" + chars + " bytes=" + bytes);
    }
}
